package com.unisal.selectaapi.recomendacao;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataAccessException;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

import com.unisal.selectaapi.recomendacao.config.EmbeddingProperties;

/**
 * Safety net: periodically enqueues jobs/candidates whose embedding is missing,
 * outdated or generated by another model (backfill of existing data, messages
 * lost while RabbitMQ was offline, model changes).
 */
@Component
public class EmbeddingReconciler {

    private static final Logger log = LoggerFactory.getLogger(EmbeddingReconciler.class);

    private final EmbeddingProperties properties;
    private final EmbeddingSchemaInitializer schema;
    private final EmbeddingRepository embeddingRepository;
    private final EmbeddingEventRelay relay;

    public EmbeddingReconciler(EmbeddingProperties properties,
            EmbeddingSchemaInitializer schema,
            EmbeddingRepository embeddingRepository,
            EmbeddingEventRelay relay) {
        this.properties = properties;
        this.schema = schema;
        this.embeddingRepository = embeddingRepository;
        this.relay = relay;
    }

    @Scheduled(
            initialDelayString = "${recomendacao.reconcile.initial-delay-ms:60000}",
            fixedDelayString = "${recomendacao.reconcile.interval-ms:600000}")
    public void reconcile() {
        if (!properties.isEnabled() || !schema.isAvailable()) {
            return;
        }
        try {
            int batch = properties.getReconcileBatchSize();
            var vagas = embeddingRepository.findStaleVagaIds(properties.getModel(), batch);
            var candidatos = embeddingRepository.findStaleCandidatoIds(properties.getModel(), batch);

            vagas.forEach(id -> relay.enqueue(new EmbeddingJobMessage(EmbeddingTarget.VAGA, id)));
            candidatos.forEach(id -> relay.enqueue(new EmbeddingJobMessage(EmbeddingTarget.CANDIDATO, id)));

            if (!vagas.isEmpty() || !candidatos.isEmpty()) {
                log.info("Reconciliação de embeddings: {} vaga(s) e {} candidato(s) enfileirados",
                        vagas.size(), candidatos.size());
            }
        } catch (DataAccessException exception) {
            log.warn("Falha na reconciliação de embeddings: {}", exception.getMostSpecificCause().getMessage());
        }
    }
}
